DROP TABLE IF EXISTS peta_sebaran;
CREATE TABLE peta_sebaran (
    id INT AUTO_INCREMENT PRIMARY KEY,
    nama_usaha VARCHAR(255) NULL,
    pemilik VARCHAR(255) NULL,
    nib VARCHAR(13) NULL,
    nik VARCHAR(16) NULL,
    no_hp VARCHAR(25) NULL,
